using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Text.RegularExpressions;
namespace Frociart {
 internal static class FlowCpp {
  internal static string TemplateNumber(double value){return Number(value);}
  internal static FlowSourceText Generate(FlowSource.Program program){using(var stream=typeof(FlowCpp).Assembly.GetManifestResourceStream("Frociart.Source.CppRuntime.txt")){if(stream==null)throw new InvalidOperationException("Il supporto C++ non è disponibile.");using(var reader=new StreamReader(stream,Encoding.UTF8))return Generate(program,reader.ReadToEnd());}}
  internal static FlowSourceText Generate(FlowSource.Program program,string runtime,string programName="fc_program"){if(String.IsNullOrWhiteSpace(runtime))throw new ArgumentException("Il supporto C++ è vuoto.");if(programName==null||!Regex.IsMatch(programName,@"\A[A-Za-z][A-Za-z_0-9]*\z")||Keywords.Contains(programName)||programName.Contains("__")||programName=="std"||programName=="frociart_support")throw new ArgumentException("Nome C++ non valido.");return new Writer(program).Generate(runtime,programName);}
  internal static string Literal(string text){if(text==null)return "Text()";var b=new StringBuilder("Text(u\"");foreach(char c in text){if(c=='"')b.Append("\\\"");else if(c=='\\')b.Append("\\\\");else if(c=='\n')b.Append("\\n");else if(c=='\r')b.Append("\\r");else if(c=='\t')b.Append("\\t");else if(c<32||c>126)b.Append("\\x").Append(((int)c).ToString("x4")).Append("\" u\"");else b.Append(c);}return b.Append("\", ").Append(text.Length).Append(')').ToString();}
  static readonly HashSet<string> Keywords=new HashSet<string>(("alignas alignof and and_eq asm atomic_cancel atomic_commit atomic_noexcept auto bitand bitor bool break case catch char char8_t char16_t char32_t class compl concept const consteval constexpr constinit const_cast continue co_await co_return co_yield decltype default delete do double dynamic_cast else enum explicit export extern false float for friend goto if inline int long mutable namespace new noexcept not not_eq nullptr operator or or_eq private protected public reflexpr register reinterpret_cast requires return short signed sizeof static static_assert static_cast struct switch synchronized template this thread_local throw true try typedef typeid typename union unsigned using virtual void volatile wchar_t while xor xor_eq").Split(' '),StringComparer.Ordinal);
  static readonly HashSet<string> Reserved=new HashSet<string>(("fc Value Vector Text TypeSpec HostRuntime Runtime std frociart_support run current checkType convert integer numberFromBits Scope0").Split(' '),StringComparer.Ordinal);
  static string Identifier(string name){if(Regex.IsMatch(name,@"\A[A-Za-z][A-Za-z_0-9]*\z")&&!name.Contains("__")&&!Keywords.Contains(name)&&!Reserved.Contains(name)&&!name.StartsWith("fc_",StringComparison.Ordinal))return name;var b=new StringBuilder("flowValue");foreach(char c in name)b.Append(((int)c).ToString("x4"));return b.ToString();}
  static string Unique(string seed,HashSet<string> names){string result=seed;int n=2;while(!names.Add(result))result=seed+"_"+(n++).ToString(CultureInfo.InvariantCulture);return result;}
  static string Bool(bool b){return b?"true":"false";}
  static string Number(double n){if(n==0)return "Value::number(0.0)";if(Math.Abs(n)<=9000000000d){long power=1;for(int digits=0;digits<=6;digits++,power*=10){double scaled=n*power;if(scaled!=Math.Floor(scaled))continue;string text=((long)Math.Abs(scaled)).ToString(CultureInfo.InvariantCulture).PadLeft(digits+1,'0');if(digits>0)text=text.Insert(text.Length-digits,".");if(n<0)text="-"+text;if(Double.Parse(text,CultureInfo.InvariantCulture)==n)return "Value::number("+text+(digits==0?".0":"")+")";}}return "Value::number(numberFromBits(0x"+BitConverter.DoubleToInt64Bits(n).ToString("x16")+"ULL))";}
  sealed class Symbol{internal string Name,Original;}
  sealed class Helper{internal string Name;internal FlowSource.Expression Expression;internal FlowSource.Block Block;internal HashSet<string> Staged;internal bool Track;}
  sealed class Writer {
   readonly FlowSource.Program program;readonly FlowSourceText.Builder output;readonly bool references;readonly Dictionary<string,string> functions=new Dictionary<string,string>(),classes=new Dictionary<string,string>();
   FlowSource.Scope scope;Dictionary<string,Symbol> names;List<Symbol> symbols;Dictionary<string,string> methods;List<Helper> helpers;int temporary;
   internal Writer(FlowSource.Program p){program=p;output=new FlowSourceText.Builder(p,"cpp");references=p.Scopes.SelectMany(s=>s.Parameters).Any(p1=>p1.ByReference);int index=0;var used=new HashSet<string>(Reserved,StringComparer.Ordinal);foreach(var s in p.Scopes){classes[s.Id??""]="FcScope"+(index++);if(s.Id!=null)functions[s.Id]=Unique("flow_"+Identifier(s.Name),used);}}
   void Line(string text,int indent,FlowSource.Block block=null){output.AddLine(text,indent,block==null?new FlowSourceText.Origin[0]:new[]{new FlowSourceText.Origin(scope.Id,block.Id)});}
   internal FlowSourceText Generate(string runtime,string programName){Line("// Generato con Frociart — autore del software: mamt104",0);Line("// Progetto: "+Literal(program.Title),0);Line("// C++17. Salva Programma.cpp; compila con g++ -std=c++17 -O2 Programma.cpp -o Programma.",0);Line("// Su Linux/macOS aggiungi -pthread.",0);Line("// Percorsi e permessi sono quelli del programma eseguito sul computer.",0);
    Line("// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---",0);foreach(string text in runtime.Replace("\r\n","\n").Replace('\r','\n').Split('\n'))Line(text,0);Line("// --- Programma ---",0);Line("namespace "+programName+" {",0);Line("using namespace frociart_support;",1);Line("static HostRuntime fc;",1);
    foreach(var s in program.Scopes.Where(s=>s.Id!=null))Line("static Value "+functions[s.Id]+"("+String.Join(", ",s.Parameters.Select((p,i)=>"Value fc_arg"+i))+");",1);
    foreach(var s in program.Scopes)WriteScope(s);
    foreach(var s in program.Scopes.Where(s=>s.Id!=null)){Line("static Value "+functions[s.Id]+"("+String.Join(", ",s.Parameters.Select((p,i)=>"Value fc_arg"+i))+") {",1);Line("return std::make_unique<"+classes[s.Id]+">()->run("+String.Join(", ",s.Parameters.Select((p,i)=>"fc_arg"+i))+");",2);Line("}",1);}
    Line("bool execute(bool saveDrawing = true) { return fc.run([](){ return std::make_unique<FcScope0>()->run(); }, saveDrawing); }",1);Line("}",0);Line("int main() { return "+programName+"::execute() ? 0 : 1; }",0);return output.Build();
   }
   void Collect(FlowSource.Expression e,Action<string> add){if(e==null)return;if(e.Kind==FlowSource.ExpressionKind.Variable)add(e.Text);foreach(var c in e.Children)Collect(c,add);}
   void WriteScope(FlowSource.Scope s){scope=s;temporary=0;names=new Dictionary<string,Symbol>(StringComparer.OrdinalIgnoreCase);symbols=new List<Symbol>();methods=new Dictionary<string,string>();helpers=new List<Helper>();var used=new HashSet<string>(Reserved,StringComparer.Ordinal);
    Action<string> add=n=>{if(n!=null&&!names.ContainsKey(n)){var symbol=new Symbol{Name=Unique("flowVar_"+Identifier(n),used),Original=n};names.Add(n,symbol);symbols.Add(symbol);}};foreach(var p in s.Parameters)add(p.Name);int index=0;
    foreach(var b in s.Blocks){methods[b.Id]="fc_block"+(index++);var o=b.Operation;if(o.Input!=null){add(o.Input.Name);Collect(o.Input.Index,add);}if(o.Declaration!=null){foreach(string n in o.Declaration.Names)add(n);Collect(o.Declaration.Size,add);}foreach(var w in o.Writes){add(w.Target.Name);Collect(w.Value,add);Collect(w.Target.Index,add);}Collect(o.Value,add);}
    Line("",0);foreach(var n in s.Notes)Line("// Annotazione: "+Literal(n.Text),1,n);foreach(var n in s.Blocks.Where(b=>!String.IsNullOrEmpty(b.Comment)))Line("// Nota: "+Literal(n.Comment),1,n);
    Line("class "+classes[s.Id??""]+" {",1);foreach(var symbol in symbols){Line("Value "+symbol.Name+";",2);Line("std::optional<TypeSpec> fc_type_"+symbol.Name+";",2);}foreach(var p in s.Parameters)Line("const TypeSpec fc_parameter_"+names[p.Name].Name+"{"+(int)p.Type+", "+Bool(p.IsArray)+", 0};",2);
    Line("public:",1);Line("Value run("+String.Join(", ",s.Parameters.Select((p,i)=>"Value fc_arg"+i))+") {",2);Line("fc.guardCall();",3);index=0;foreach(var p in s.Parameters)Line(names[p.Name].Name+" = "+(p.ByReference?"fc.checkReference(fc_arg"+(index++)+", "+(int)p.Type+")":"checkType(fc_arg"+(index++)+", "+(int)p.Type+", "+Bool(p.IsArray)+")")+";",3);
    Line("return fc.invoke("+(s.Id==null?"std::nullopt":"std::optional<Text>("+Literal(s.Name)+")")+", {"+String.Join(", ",s.Parameters.Select(p=>Literal(names[p.Name].Original)))+"}, {"+String.Join(", ",s.Parameters.Select((p,i)=>"fc_arg"+i))+"}, [&]() -> Value {",3);
    var plan=FlowSourcePlan.Create(s);if(plan.Structured)Statements(plan.Statements,4);else Explicit(4);Line("}, "+Bool(references)+");",3);Line("}",2);Line("private:",1);foreach(var b in s.Blocks)Instruction(b);
    for(int i=0;i<helpers.Count;i++){var h=helpers[i];Line("Value "+h.Name+"() {",2,h.Block);string expr=Expression(h.Expression,h.Block,h.Staged,0,h.Track);Line("return "+expr+";",3,h.Block);Line("}",2,h.Block);}Line("};",1);
   }
   string Name(string name,HashSet<string> staged){var sym=names[name];string value=references?"fc.current("+Literal(sym.Original)+")":staged.Contains(sym.Original)?"fc.staged("+Literal(sym.Original)+")":sym.Name;return "fc.value("+value+", "+Literal(name)+")";}
   string Declaration(string name){return "(fc_type_"+names[name].Name+" ? &*fc_type_"+names[name].Name+" : nullptr)";}
   string Parameter(string name){return scope.Parameters.Any(p=>p.Name.Equals(name,StringComparison.OrdinalIgnoreCase))?"&fc_parameter_"+names[name].Name:"nullptr";}
   bool Calls(FlowSource.Expression e){return e!=null&&(e.FunctionId!=null||e.Children.Any(Calls));}
   string Expression(FlowSource.Expression e,FlowSource.Block b){return Expression(e,b,new HashSet<string>(StringComparer.OrdinalIgnoreCase),0,false);}
   string Expression(FlowSource.Expression e,FlowSource.Block block,HashSet<string> staged,int depth,bool track){if(e==null)return "Value()";if(depth==0)track|=Calls(e);if(depth>=24){string helper="fc_expr"+(++temporary);helpers.Add(new Helper{Name=helper,Expression=e,Block=block,Staged=new HashSet<string>(staged,StringComparer.OrdinalIgnoreCase),Track=track});return helper+"()";}
    int key=track?++temporary:0;Func<FlowSource.Expression,string> child=c=>{string v=Expression(c,block,staged,depth+1,track);return track?"fc.hold("+key+", "+v+")":v;};Func<string,string> finish=v=>track&&e.Children.Count>0?"fc.release("+key+", "+v+")":v;
    switch(e.Kind){case FlowSource.ExpressionKind.Number:return Number(e.Number);case FlowSource.ExpressionKind.Text:return "Value::text("+Literal(e.Text)+")";case FlowSource.ExpressionKind.Boolean:return "Value::logical("+Bool(e.Boolean)+")";case FlowSource.ExpressionKind.Variable:return Name(e.Text,staged);case FlowSource.ExpressionKind.Vector:return finish("Value::vector({"+String.Join(", ",e.Children.Select(child))+"})");
     case FlowSource.ExpressionKind.Index:{bool named=references&&e.Children[0].Kind==FlowSource.ExpressionKind.Variable;return finish(named?"fc.atName("+Literal(names[e.Children[0].Text].Original)+", [&](){ return "+child(e.Children[1])+"; })":"fc.at("+child(e.Children[0])+", [&](){ return "+child(e.Children[1])+"; })");}
     case FlowSource.ExpressionKind.Unary:return finish("fc.unary(\""+e.Text+"\", "+child(e.Children[0])+")");
     case FlowSource.ExpressionKind.Binary:{string a=child(e.Children[0]),c=child(e.Children[1]);if(e.Text=="and"||e.Text=="or")return finish("Value::logical(("+a+").asBoolean() "+(e.Text=="and"?"&&":"||")+" ("+c+").asBoolean())");return "([&]() -> Value { auto fc_left = "+a+"; auto fc_right = "+c+"; return "+finish("fc.binary(\""+e.Text+"\", fc_left, fc_right)")+"; }())";}
     case FlowSource.ExpressionKind.Call:{if(e.FunctionId==null)return finish("fc.intrinsic(\""+e.Text+"\", {"+String.Join(", ",e.Children.Select(child))+"})");var target=program.Scopes.First(s=>s.Id==e.FunctionId);var parts=new List<string>();for(int i=0;i<e.Children.Count;i++){var c=e.Children[i];string value=target.Parameters[i].ByReference?"fc.hold("+key+", fc.reference("+Literal(names[c.Text].Original)+", "+Declaration(c.Text)+", "+Parameter(c.Text)+"))":child(c);parts.Add("auto fc_argument"+i+" = "+value+"; ");}return "fc.call("+key+", [&]() -> Value { "+String.Concat(parts)+"return "+functions[e.FunctionId]+"("+String.Join(", ",e.Children.Select((c,i)=>"fc_argument"+i))+"); })";}
     default:throw new ArgumentException("Espressione C++ non supportata.");}
   }
   void Statements(IEnumerable<FlowSourcePlan.Statement> list,int indent){foreach(var s in list){if(s.Kind==FlowSourcePlan.Kind.Instruction)Line((s.Block.Kind==NodeKind.End?"return ":"")+methods[s.Block.Id]+"();",indent,s.Block);else if(s.Kind==FlowSourcePlan.Kind.Repeat){Line("do {",indent,s.EntryBlock);Statements(s.Body,indent+1);Line("} while ("+(s.LoopOnTrue?"":"!")+methods[s.Block.Id]+"().asBoolean());",indent,s.Block);}else if(s.Kind==FlowSourcePlan.Kind.While){Line("while ("+(s.LoopOnTrue?"":"!")+methods[s.Block.Id]+"().asBoolean()) {",indent,s.Block);Statements(s.Body,indent+1);Line("}",indent,s.Block);}else{Line("if ("+methods[s.Block.Id]+"().asBoolean()) {",indent,s.Block);Statements(s.Body,indent+1);Line("} else {",indent,s.Block);Statements(s.Otherwise,indent+1);Line("}",indent,s.Block);}}}
   void Explicit(int indent){Line("// Collegamenti espliciti per conservare questo grafo.",indent);var ids=scope.Blocks.Select((b,i)=>new{b.Id,Index=i}).ToDictionary(p=>p.Id,p=>p.Index);Line("int fc_next = "+ids[scope.StartId]+";",indent);Line("while (true) {",indent);Line("switch (fc_next) {",indent+1);foreach(var b in scope.Blocks){Line("case "+ids[b.Id]+":",indent+2,b);if(b.Kind==NodeKind.End)Line("return "+methods[b.Id]+"();",indent+3,b);else if(b.Kind==NodeKind.Decision)Line("fc_next = "+methods[b.Id]+"().asBoolean() ? "+ids[b.Next("true")]+" : "+ids[b.Next("false")]+"; break;",indent+3,b);else{Line(methods[b.Id]+"();",indent+3,b);Line("fc_next = "+ids[b.Next("next")]+"; break;",indent+3,b);}}Line("default: throw Problem(\"Collegamento non valido nel sorgente modificato.\");",indent+2);Line("}",indent+1);Line("}",indent);}
   void Instruction(FlowSource.Block b){var o=b.Operation;Line("Value "+methods[b.Id]+"() {",2,b);Action<string> emit=t=>Line(t,3,b);if(b.Kind==NodeKind.Decision){emit("return Value::logical(fc.test([&](){ return "+Expression(o.Value,b)+"; }));");Line("}",2,b);return;}emit(b.Kind==NodeKind.Input?"fc.guard();":"fc.step();");
    if(b.Kind==NodeKind.End){if(scope.Id==null)emit("fc.finishFiles();");emit(scope.Id==null||scope.ReturnType==FlowDataType.Void?"return Value();":"return checkType("+Expression(o.Value,b)+", "+(int)scope.ReturnType+", "+Bool(scope.ReturnIsArray)+");");Line("}",2,b);return;}
    if(b.Kind==NodeKind.Process){emit("fc.begin();");var staged=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var assignments=o.Writes.Select(w=>"fc_assign"+(++temporary)).ToArray();foreach(string assignment in assignments)emit(assignment+"();");emit("fc.commit();");foreach(var w in o.Writes)if(staged.Add(names[w.Target.Name].Original))emit(names[w.Target.Name].Name+" = fc.variable("+Literal(names[w.Target.Name].Original)+");");emit("return Value();");Line("}",2,b);staged.Clear();for(int i=0;i<o.Writes.Count;i++){var w=o.Writes[i];Line("void "+assignments[i]+"() {",2,b);Line("auto fc_value = "+Expression(w.Value,b,staged,0,false)+";",3,b);if(w.Target.Index!=null)Line("fc_value = "+(references?"fc.setAfterName(fc_value, "+Literal(names[w.Target.Name].Original):"fc.setAfter(fc_value, "+Name(w.Target.Name,staged))+", [&](){ return "+Expression(w.Target.Index,b,staged,0,false)+"; });",3,b);Line("fc.stage("+Literal(names[w.Target.Name].Original)+", convert(fc_value, "+Declaration(w.Target.Name)+", "+Parameter(w.Target.Name)+"), true, "+Bool(w.Target.Index!=null)+");",3,b);Line("}",2,b);staged.Add(names[w.Target.Name].Original);}return;}
    if(b.Kind==NodeKind.Declare){var d=o.Declaration;emit("int fc_size = integer("+(d.IsArray?Expression(d.Size,b):"Value::number(0)")+", 0, 1024, \"La dimensione\");");emit("fc.begin();");foreach(string n in d.Names)emit("fc.stage("+Literal(names[n].Original)+", initial("+(int)d.Type+", "+Bool(d.IsArray)+", fc_size), false);");emit("fc.commit(true);");foreach(string n in d.Names){emit(names[n].Name+" = fc.variable("+Literal(names[n].Original)+");");emit("fc_type_"+names[n].Name+" = TypeSpec{"+(int)d.Type+", "+Bool(d.IsArray)+", fc_size};");}}
    else if(b.Kind==NodeKind.Input||b.Kind==NodeKind.ReadFile){var t=o.Input;string tail=Declaration(t.Name)+", "+Parameter(t.Name)+", "+(t.Index==null?"Value(), {}":Name(t.Name,new HashSet<string>(StringComparer.OrdinalIgnoreCase))+", [&](){ return "+Expression(t.Index,b)+"; }");emit(names[t.Name].Name+" = fc."+(b.Kind==NodeKind.Input?"read(":"readFile(")+Literal(names[t.Name].Original)+", "+(b.Kind==NodeKind.Input?Literal(b.Prompt??"")+", ":"")+tail+");");if(b.Kind==NodeKind.Input)emit("fc.step();");}
    else if(b.Kind!=NodeKind.Start&&b.Kind!=NodeKind.Pause){if(b.Kind==NodeKind.OpenFile)emit("fc.requireClosed("+Bool(o.FileReading)+");");if(b.Kind==NodeKind.WriteFile)emit("fc.requireWrite();");string e=Expression(o.Value,b);switch(b.Kind){case NodeKind.Output:emit("fc.emit("+e+", "+Bool(o.OutputNewline)+");");break;case NodeKind.Call:emit(e+";");break;case NodeKind.OpenFile:emit("fc.openFile("+Bool(o.FileReading)+", "+e+");");break;case NodeKind.WriteFile:emit("fc.writeFile("+e+", "+Bool(o.FileNewline)+");");break;case NodeKind.CloseFile:emit("fc.closeFile("+Bool(o.FileReading)+");");break;case NodeKind.TurtleForward:case NodeKind.TurtleTurn:case NodeKind.TurtleHome:case NodeKind.TurtleClear:case NodeKind.TurtlePen:emit("fc.turtle("+(int)b.Kind+", "+e+", "+Bool(b.Kind==NodeKind.TurtleForward?o.TurtleDraw:o.TurtleLeft)+");");break;default:throw new ArgumentException("Blocco C++ non supportato.");}}
    emit("return Value();");Line("}",2,b);
   }
  }
 }
